// Turns DevFlow events into chat messages. Plan-ready events get a signed approval link
// handled by the "DevFlow - approve plan from link" workflow.
const crypto = require('crypto');
const CONFIG = {
  n8nUrl: 'http://localhost:5678',            // where your phone/browser can reach n8n
  approvalLinkSecret: 'CHANGE-ME-link-secret', // must match the approval workflow
  linkHours: 24,
};
const ICONS = { plan_ready: '📝', workflow_halted: '⛔', safety_violation: '🚨', limit_reached: '💸', model_error: '⚠️', delivered: '✅', ping: '🔔' };

const out = [];
for (const item of $input.all()) {
  const e = item.json.body ?? item.json;
  if (!e || !e.event) continue;
  const p = e.project;
  const head = p ? `${p.name} (#${p.id})` : 'DevFlow';
  let text = `${ICONS[e.event] ?? 'ℹ️'} ${head}\n${e.event.replace(/_/g, ' ')}: ${e.message}`;
  if (p) text += `\nStatus: ${p.status}${p.status_reason ? ' — ' + p.status_reason : ''}\n${e.links.dashboard}`;
  if (e.event === 'plan_ready' && p) {
    const exp = Math.floor(Date.now() / 1000) + CONFIG.linkHours * 3600;
    const sig = crypto.createHmac('sha256', CONFIG.approvalLinkSecret).update(`${p.id}:${p.plan_version}:${exp}`).digest('hex');
    text += `\n\nApprove plan v${p.plan_version}: ${CONFIG.n8nUrl}/webhook/devflow-approve?project=${p.id}&version=${p.plan_version}&exp=${exp}&sig=${sig}`;
  }
  out.push({ json: { text, event: e.event, project_id: p ? p.id : null } });
}
return out;
